        if (!s) { pic.replaceChildren(el('p', { class: 'a-hint', text: 'Знак не прочитался.' })); return; }
        var n = M.svgNode(s, /^#[0-9a-f]{3,6}$/i.test(Mk.color || '') ? Mk.color : '#ffe2a0', Mk);
        pic.replaceChildren(n); M.svgDraw(n, (+Mk.draw || 3) * 1000);
