    var i = el(o.line ? 'input' : 'textarea', { class: 'a-input', placeholder: o.ph || '', rows: o.line ? null : Math.max(o.rows || 2, Math.min(o.max || 14, Math.ceil(v.length / 85) + v.split('\n').length - 1)) });
    i.value = v;
