        if (!d) { if (s.type !== 'result') { W.steps.splice(Math.max(0, W.steps.length - 1), 0, clone(s)); ch.push('Новый вопрос «' + (s.text || s.id) + '» (тексты итога для него — вкладка «Итог»)'); } return; }
        set(d, 'text', s.text, what);
